"""Версионируемые исходные описания открытого и авторского наборов вопросов."""

from __future__ import annotations


def item(
    ident: str,
    category: str,
    question: str,
    options: list[str],
    answer_ids: list[str],
    pages: list[int],
    rationale: str,
    missing_information: str | None = None,
) -> dict:
    return {
        "id": ident,
        "category": category,
        "question": question,
        "options": [{"id": chr(65 + number), "text": text} for number, text in enumerate(options)],
        "answer_ids": answer_ids,
        "pages": pages,
        "rationale": rationale,
        "missing_information": missing_information,
    }


